  for (let item of d) {
    if (item.value && item.value[0] && item.value[0] !== "0.0.0.0") {
      result = item.value[0];
      break;
    }
  }
  if (!result) {
    let d2 = declare("InternetGatewayDevice.ManagementServer.ConnectionRequestURL", {value: 1});
    for (let item of d2) {
      if (item.value && item.value[0]) {
        let str = item.value[0];
        let idx = str.indexOf("://");
        if (idx !== -1) {
          let rest = str.substring(idx + 3);
          let slashIdx = rest.indexOf("/");
          if (slashIdx !== -1) rest = rest.substring(0, slashIdx);
          let colonIdx = rest.indexOf(":");
          if (colonIdx !== -1) rest = rest.substring(0, colonIdx);
          result = rest;
        }
        break;
      }
    }
  }
}

return {writable: false, value: [result, "xsd:string"]};

