  "InternetGatewayDevice.WANDevice.*.X_FH_GponInterfaceConfig.RXPower",
  "InternetGatewayDevice.WANDevice.*.X_FH_EponInterfaceConfig.RXPower"
];

for (let k of keys) {
  let d = declare(k, {value: 1});
  for (let item of d) {
    if (item.value && item.value[0] !== undefined && item.value[0] !== null && item.value[0] !== "") {
      let raw = Number(item.value[0]);
      if (!isNaN(raw)) {
        if (raw < 0) {
          m = String(raw);
        } else if (raw > 0) {
          let db = 30 + (Math.log10(raw * Math.pow(10, -7)) * 10);
          m = String(Math.ceil(db * 100) / 100);
        }
        break;
      }
    }
  }
  if (m) break;
}

return {writable: false, value: [m, "xsd:string"]};

// WLAN Password with Smart Persistence (Falls back to cached value if ONT hides it)
let m = "";
let cachedPass = "";
let dCache = declare("InternetGatewayDevice.DeviceInfo.X_CT-COM_CardKey", {value: 1});
if (dCache.size && dCache.value && dCache.value[0]) {
  cachedPass = dCache.value[0];
}

if (args[1] && args[1].value) {
  m = args[1].value[0];
  // Write to ONT wireless parameters
  declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.KeyPassphrase", null, {value: m});
  declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.PreSharedKey.1.KeyPassphrase", null, {value: m});
  // Save persistent copy into internal storage so it is never lost
  declare("InternetGatewayDevice.DeviceInfo.X_CT-COM_CardKey", null, {value: m});
} else {
  let d1 = declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.KeyPassphrase", {value: 1});
  for (let item of d1) {
    if (item.value && item.value[0]) {
      m = item.value[0];
      break;
    }
  }
  if (!m) {
    let d2 = declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.PreSharedKey.*.KeyPassphrase", {value: 1});
    for (let item of d2) {
      if (item.value && item.value[0]) {
        m = item.value[0];
        break;
      }
    }
  }
  if (!m) {
    let d3 = declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.PreSharedKey.*.PreSharedKey", {value: 1});
    for (let item of d3) {
      if (item.value && item.value[0]) {
        m = item.value[0];
        break;
      }
    }
  }
  // If ONT returned empty (e.g. ZTE/AZV read protection), use previously stored password
  if (!m && cachedPass) {
    m = cachedPass;
  }
}

return {writable: true, value: [m, "xsd:string"]};

